package org.jkiss.dbeaver.teststudio.core;
import com.google.gson.*;import java.nio.charset.StandardCharsets;import org.jkiss.dbeaver.teststudio.spi.TestReportProvider;
final class MarkdownReportProvider implements TestReportProvider{public String format(){return "markdown";}public String extension(){return "md";}public byte[] generate(JsonObject run,JsonObject options){StringBuilder out=new StringBuilder("# ").append(StudioJson.string(run,"name","Test Studio Run")).append("\n\n");out.append("- Run: `").append(StudioJson.string(run,"run_id","")).append("`\n- State: **").append(StudioJson.string(run,"state","unknown")).append("**\n- Passed: **").append(StudioJson.bool(run,"passed",false)).append("**\n\n## Steps\n\n| Step | Type | Status | Duration ms |\n|---|---|---|---:|\n");for(JsonElement e:StudioJson.array(run,"steps")){JsonObject s=e.getAsJsonObject();out.append('|').append(clean(StudioJson.string(s,"id",""))).append('|').append(clean(StudioJson.string(s,"type",""))).append('|').append(clean(StudioJson.string(s,"status",""))).append('|').append(s.has("elapsed_ms")?String.format(java.util.Locale.ROOT,"%.1f",s.get("elapsed_ms").getAsDouble()):"").append("|\n");}out.append("\n## Cleanup\n\n```json\n").append(StudioJson.GSON.toJson(StudioJson.object(run,"cleanup"))).append("\n```\n");return out.toString().getBytes(StandardCharsets.UTF_8);}private static String clean(String s){return s.replace("|","\\|").replace("\n"," ");}}
